    67→async function WeekViewLoader() {
    68→  const org = await getRequiredCurrentOrg();
    69→  const today = new Date();
    70→  const weekAgo = subDays(today, 6);
    71→
    72→  const entries = await getMoodEntries({
    73→    userId: org.user.id,
    74→    organizationId: org.id,
    75→    startDate: weekAgo,
    76→    endDate: today,
    77→    limit: 7,
    78→  });
    79→
    80→  // Build week data
    81→  const weekData = Array.from({ length: 7 }, (_, i) => {
    82→    const date = subDays(today, 6 - i);
    83→    const entry = entries.find(
    84→      (e) => format(new Date(e.date), "yyyy-MM-dd") === format(date, "yyyy-MM-dd"),
    85→    );
    86→    return {
    87→      day: format(date, "EEE", { locale: fr }),
    88→      mood: entry?.mood as MoodValueBipolar | null ?? null,
    89→    };
    90→  });
    91→
    92→  return (
    93→    <Card>
    94→      <CardHeader>
    95→        <CardTitle className="text-lg">Cette semaine</CardTitle>
    96→      </CardHeader>
    97→      <CardContent>
    98→        <WeekMoodViewBipolar data={weekData} />
    99→      </CardContent>
   100→    </Card>
   101→  );
   102→}
